(()=>{"use strict";const t=class{constructor(t){this.length=t,this.hits=0}hit(){this.hits++}isSunk(){return this.hits>=this.length}},s=class{constructor(){this.board=Array(10).fill(null).map((()=>Array(10).fill(null))),this.ships=[],this.missedAttacks=[]}placeShip(s,r){const e=new t(s);r.forEach((([t,s])=>this.board[t][s]=e)),this.ships.push(e)}receiveAttack(s,r){const e=this.board[s][r];return e instanceof t?(e.hit(),e.isSunk()&&console.log("Ship sunk!"),!0):(this.missedAttacks.push([s,r]),!1)}allShipsSunk(){return this.ships.every((t=>t.isSunk()))}},r=class{constructor(t=!1){this.board=new s,this.isComputer=t}makeRandomAttack(){let t,s;do{t=Math.floor(10*Math.random()),s=Math.floor(10*Math.random())}while(this.board.missedAttacks.some((([r,e])=>r===t&&e===s)));return[t,s]}};(new class{constructor(){this.player=new r,this.computer=new r(!0),this.currentPlayer=this.player}start(){this.setupBoards(),this.setupUI()}setupBoards(){this.player.board.placeShip(4,[[0,0],[0,1],[0,2],[0,3]]),this.computer.board.placeShip(4,[[5,5],[5,6],[5,7],[5,8]])}setupUI(){document.querySelectorAll(".cell").forEach((t=>{t.addEventListener("click",(t=>this.handlePlayerAttack(t)))}))}handlePlayerAttack(t){const[s,r]=t.target.dataset.coords.split(",").map(Number);this.computer.board.receiveAttack(s,r),this.updateUI(),this.computer.board.allShipsSunk()?alert("Player wins!"):(this.switchTurn(),this.currentPlayer.isComputer&&this.handleComputerAttack())}handleComputerAttack(){const[t,s]=this.computer.makeRandomAttack();this.player.board.receiveAttack(t,s),this.updateUI(),this.player.board.allShipsSunk()?alert("Computer wins!"):this.switchTurn()}switchTurn(){this.currentPlayer=this.currentPlayer===this.player?this.computer:this.player}updateUI(){}}).start()})();